function f = HS28_f(x)
f = (x(1) + x(2)).^2 + (x(2) + x(3)).^2;
end

function g = HS28_g(x)
g = zeros(3, 1);
g(1) = 2*x(1) + 2*x(2);
g(2) = 2*x(1) + 4*x(2) + 2*x(3);
g(3) = 2*x(2) + 2*x(3);
end

function c = HS28_c(x)
c = zeros(1, 1);
c(1) = x(1) + 2*x(2) + 3*x(3) - 1;
end

function J = HS28_J(x)
